import{_ as r,o as e,c as a,a2 as o}from"./chunks/framework.BAAh_OrB.js";const u=JSON.parse('{"title":"功能特性","description":"","frontmatter":{"title":"功能特性"},"headers":[],"relativePath":"miniprogram/features.md","filePath":"miniprogram/features.md","lastUpdated":1787652964000}'),i={name:"miniprogram/features.md"};function l(n,t,d,s,h,c){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h1><h2 id="_1-agorain-课堂签到-checkin" tabindex="-1">1. AgoraIn 课堂签到（checkin） <a class="header-anchor" href="#_1-agorain-课堂签到-checkin" aria-label="Permalink to &quot;1. AgoraIn 课堂签到（checkin）&quot;">​</a></h2><p>对接局域网 AgoraIn 打卡服务器，实现课堂签到全流程（数据通过 <code>wx.request</code> 与服务器交互，Bearer Token 认证）：</p><ul><li><strong>登录认证</strong>：账号密码登录，区分管理员 / 普通教师 / 学生 / 家长四种角色；登录后按角色自动跳转对应首页，支持登出</li><li><strong>管理端仪表盘</strong>：设备在线状态、今日签到统计、活跃签到任务概览；支持设备重命名 / 删除、快速创建签到任务</li><li><strong>签到任务管理</strong>：签到任务列表，支持查看任务二维码、签到情况</li><li><strong>生成签到</strong>：选择打卡设备、填写课程 / 教室 / 签到密码 / 学生名单，一键生成签到码与二维码海报</li><li><strong>学生签到</strong>：扫码或手动输入签到码完成签到，提交姓名与签到密码，实时显示签到结果与名次</li><li><strong>考勤详情</strong>：按任务或设备维度查看应到 / 已签 / 未签人数与签到率</li><li><strong>个人历史</strong>：学生视角查看历史签到记录与累计统计</li><li><strong>用户管理</strong>：管理员创建用户并分配角色（学生 / 家长 / 教师 / 管理员）</li><li><strong>服务器发现</strong>：支持 mDNS 局域网自动发现服务器地址，也可手动填写</li></ul><h2 id="_2-课堂打卡-本地版" tabindex="-1">2. 课堂打卡（本地版） <a class="header-anchor" href="#_2-课堂打卡-本地版" aria-label="Permalink to &quot;2. 课堂打卡（本地版）&quot;">​</a></h2><p>独立的本地课堂打卡模块（数据存储键前缀 <code>ck_</code>，不依赖服务器，数据保存在本机）：</p><ul><li>班级 / 课程配置：学校、年级、班级、课程名称，座位网格布局（行 × 列）</li><li>学生名单管理</li><li>每日打卡记录：按日期存储签到名单与签到时间</li></ul><h2 id="_3-课时划消-classhours" tabindex="-1">3. 课时划消（classhours） <a class="header-anchor" href="#_3-课时划消-classhours" aria-label="Permalink to &quot;3. 课时划消（classhours）&quot;">​</a></h2><p>独立的本地课时管理工具（数据存储键前缀 <code>ch_</code>，与课堂打卡数据完全隔离）：</p><ul><li><strong>课时管理</strong>：添加学生、设置初始课时、扣课时 / 加课时（支持填写变动原因）</li><li><strong>课时明细</strong>：学生详情页展示课时变动记录与剩余课时，支持编辑学生信息（姓名 / 课程 / 备注）、删除学生</li><li><strong>课时进度可视化</strong>：列表页展示每个学生的课时进度</li><li><strong>批量导入</strong>：Excel / CSV 批量导入学生，支持下载导入模板、重复数据自动跳过</li><li><strong>数据导入 / 导出</strong>：JSON 完整备份与恢复导入（含课时设置）、CSV 学生清单导出、数据复制到剪贴板</li><li><strong>排课管理</strong>：按日期添加上课时间段（如 12:00-14:00）并勾选学生，详情展示每个时间段的时长与预计课时 / 人，支持排课数据导出 / 导入（自动兼容旧版数据结构）</li><li><strong>自动销课时</strong>：在课时设置中配置每小时消耗课时数（支持小数），一键按排课时间段自动扣除每位学生的课时（时长 × 费率），已销课的记录自动跳过、不重复扣减</li></ul><h2 id="客户端平台" tabindex="-1">客户端平台 <a class="header-anchor" href="#客户端平台" aria-label="Permalink to &quot;客户端平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td>微信小程序</td><td>微信内即用，无需安装，功能完整</td></tr><tr><td>Android</td><td>独立 App，<a href="/download.html">点击下载</a></td></tr><tr><td>iOS</td><td>暂未提供（无开发者证书，无法签名构建）</td></tr></tbody></table><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>说明</th></tr></thead><tbody><tr><td>框架</td><td>原生微信小程序（JavaScript + WXML + WXSS，ES6 模块）</td></tr><tr><td>UI 组件</td><td>TDesign 微信小程序组件库</td></tr><tr><td>渲染</td><td>WebView / Skyline（部分页面）</td></tr><tr><td>基础库</td><td>3.6.3</td></tr><tr><td>数据存储</td><td>本地存储（wx.setStorageSync）</td></tr><tr><td>网络</td><td>wx.request 封装（Bearer Token 认证）</td></tr><tr><td>其他</td><td>深色模式（darkmode）、分包加载（lazyCodeLoading）、mDNS 局域网发现</td></tr></tbody></table><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="https://github.com/liuyuchen012/AgoraIn" target="_blank" rel="noreferrer">AgoraIn 上游项目（GitHub）</a></li><li><a href="https://doc.615mc.cn" target="_blank" rel="noreferrer">AgoraIn 项目官网 / 使用文档</a></li><li><a href="https://tdesign.tencent.com/miniprogram/overview" target="_blank" rel="noreferrer">TDesign 小程序组件库文档</a></li><li><a href="https://developers.weixin.qq.com/miniprogram/dev/framework/" target="_blank" rel="noreferrer">微信小程序开发文档</a></li></ul>',16)])])}const m=r(i,[["render",l]]);export{u as __pageData,m as default};
